declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/doctor_online_v580.php';$me=require_login();$doc=do580_doctor_by_user((int)$me['id']);if(!$doc){header('Location: /doctor-signup.php');exit;}$flash='';$error='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{csrf_check();$a=(string)($_POST['action']??'');if($a==='presence'){$st=in_array((string)($_POST['online_status']??''),['offline','available','busy','away'],true)?(string)$_POST['online_status']:'offline';db()->prepare('UPDATE health_doctors_v580 SET online_status=?,instant_consult=?,updated_at=NOW() WHERE id=? AND user_id=?')->execute([$st,!empty($_POST['instant_consult'])?1:0,(int)$doc['id'],(int)$me['id']]);$flash='Online availability updated.';}elseif($a==='add_availability'){$wd=max(0,min(6,(int)($_POST['weekday']??0)));$start=(string)($_POST['start_time']??'09:00');$end=(string)($_POST['end_time']??'13:00');if($start>=$end)throw new RuntimeException('End time must be after start time.');$mode=in_array((string)($_POST['consultation_mode']??''),['online','in_person','both'],true)?(string)$_POST['consultation_mode']:'both';db()->prepare('INSERT INTO health_doctor_availability_v580(tenant_id,doctor_id,organization_id,weekday,start_time,end_time,slot_minutes,consultation_mode,status,created_at) VALUES(?,?,?,?,?,?,?,?,1,NOW())')->execute([do580_tid(),(int)$doc['id'],(int)($_POST['organization_id']??0)?:((int)($doc['primary_org_id']??0)?:null),$wd,$start,$end,max(10,min(120,(int)($_POST['slot_minutes']??20))),$mode]);$flash='Availability block added.';}elseif($a==='delete_availability'){db()->prepare('DELETE FROM health_doctor_availability_v580 WHERE id=? AND doctor_id=? AND tenant_id=?')->execute([(int)$_POST['availability_id'],(int)$doc['id'],do580_tid()]);$flash='Availability removed.';}elseif($a==='appointment_status'){$appt=do580_appointment((int)($_POST['appointment_id']??0));if(!$appt||(int)$appt['doctor_id']!==(int)$doc['id'])throw new RuntimeException('Appointment not found.');$st=in_array((string)($_POST['status']??''),['confirmed','waiting','in_progress','completed','cancelled','rejected','no_show'],true)?(string)$_POST['status']:'confirmed';$extra='';if($st==='confirmed')$extra=',confirmed_at=NOW()';if($st==='in_progress')$extra=',started_at=NOW()';if($st==='completed')$extra=',completed_at=NOW()';db()->prepare("UPDATE health_appointments_v580 SET status=?$extra,updated_at=NOW() WHERE id=? AND doctor_id=?")->execute([$st,(int)$appt['id'],(int)$doc['id']]);if($st==='completed')db()->prepare('UPDATE health_doctors_v580 SET total_consultations=total_consultations+1 WHERE id=?')->execute([(int)$doc['id']]);$flash='Appointment status updated.';}}catch(Throwable $e){$error=$e->getMessage();}$doc=do580_doctor_by_user((int)$me['id']);}$appts=do580_doctor_appointments((int)$doc['id']);$avail=do580_availability((int)$doc['id']);$sub=do580_doctor_subscription((int)$doc['id']);$today=array_filter($appts,fn($a)=>date('Y-m-d',strtotime($a['scheduled_at']))===date('Y-m-d'));$upcoming=array_filter($appts,fn($a)=>strtotime($a['scheduled_at'])>=time()&&!in_array($a['status'],['cancelled','rejected','completed','no_show'],true));do580_public_header('Doctor Portal','Doctor workspace for appointments, online status, schedule and consultations.');
