<section class="do580-pagehead"><div class="do580-shell"><h1>Doctor Portal</h1><p><?=e($doc['display_name'])?> · <?=e($doc['specialty_name']?:'Medical Doctor')?> · Profile <?=e($doc['approval_status'])?></p></div></section><main class="do580-shell" style="padding:28px 0 56px"><?php if($flash):?><div class="do580-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="do580-alert err"><?=e($error)?></div><?php endif;?><?php if($doc['approval_status']!=='approved'):?><div class="do580-alert err">Your profile is not approved yet. Public booking and consultation access remain disabled until healthcare admin verification.</div><?php endif;?><div class="do580-dashboard-grid"><div class="do580-stat"><small>Today</small><b><?=count($today)?></b></div><div class="do580-stat"><small>Upcoming</small><b><?=count($upcoming)?></b></div><div class="do580-stat"><small>Total consultations</small><b><?=(int)$doc['total_consultations']?></b></div><div class="do580-stat"><small>Rating</small><b>★ <?=number_format((float)$doc['rating'],1)?></b></div></div><div class="do580-main-grid" style="margin-top:18px"><div><section class="do580-panel"><div class="do580-head" style="margin-bottom:12px"><div><span>APPOINTMENTS</span><h2>Patient schedule</h2></div></div><div style="overflow:auto"><table class="do580-table"><thead><tr><th>Patient</th><th>Time</th><th>Mode</th><th>Fee</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($appts as $a):?><tr><td><b><?=e($a['patient_name'])?></b><br><small><?=e($a['appointment_no'])?></small></td><td><?=e(date('d M · h:i A',strtotime($a['scheduled_at'])))?></td><td><?=e(str_replace('_',' ',$a['consultation_mode']))?></td><td><?=do580_money((float)$a['fee'])?><br><small><?=e($a['payment_status'])?></small></td><td><span class="do580-status <?=e($a['status'])?>"><?=e($a['status'])?></span></td><td><form method="post" style="display:flex;gap:5px;flex-wrap:wrap"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="appointment_status"><input type="hidden" name="appointment_id" value="<?=(int)$a['id']?>"><select name="status" style="padding:7px"><option value="confirmed">Confirm</option><option value="waiting">Waiting</option><option value="in_progress">In progress</option><option value="completed">Complete</option><option value="cancelled">Cancel</option><option value="no_show">No show</option></select><button class="do580-btn secondary" style="padding:7px 9px">Update</button><?php if(in_array($a['consultation_mode'],['video','audio','chat'],true)&&in_array($a['status'],['confirmed','waiting','in_progress','completed'],true)):?><a class="do580-btn primary" style="padding:7px 9px" href="/health-consultation.php?appointment=<?=(int)$a['id']?>"><?=$a['status']==='completed'?'Review Room':'Open Room'?></a><?php endif;?></form></td></tr><?php endforeach;?><?php if(!$appts):?><tr><td colspan="6">No appointments yet.</td></tr><?php endif;?></tbody></table></div></section></div><aside><section class="do580-panel"><h3>Live availability</h3><form method="post" class="do580-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="presence"><label>Status<select name="online_status"><option value="offline" <?=$doc['online_status']==='offline'?'selected':''?>>Offline</option><option value="available" <?=$doc['online_status']==='available'?'selected':''?>>Available online</option><option value="busy" <?=$doc['online_status']==='busy'?'selected':''?>>Busy</option><option value="away" <?=$doc['online_status']==='away'?'selected':''?>>Away</option></select></label><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" style="width:auto" name="instant_consult" value="1" <?=$doc['instant_consult']?'checked':''?>> Accept instant consult requests</label><button class="do580-btn primary">Save Status</button></form></section><section class="do580-panel"><h3>Subscription</h3><?php if(